// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a single bytes input to call through external ABI encoding (keeps it general)
    function testFuzz_property(bytes memory junk) public {
        // The call has no parameters, but we accept a fuzzed bytes input so the fuzzer can vary the calldata environment.
        // We perform a low-level staticcall to the external function selector for version() so we observe the actual return value.

        // selector for version(): bytes4(keccak256("version()")) = 0x8f283970
        bytes memory sel = abi.encodeWithSelector(bytes4(0x8f283970));

        (bool ok, bytes memory ret) = address(c).staticcall(sel);

        // decode only if call succeeded; if it reverted ok==false
        string memory v;
        if (ok) {
            // decode returned string
            v = abi.decode(ret, (string));
        } else {
            v = "__REVERTED__";
        }

        // General rule: reference always returns literal "1.0.0" for any call to version(); mutant returns a different literal for some inputs.
        // Assert that the observed return equals "1.0.0". This holds for the reference for all inputs, and fails on the mutant for inputs where it returns "1.0.1".
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: arbitrary bytes input which will be passed as calldata in a low-level call.
    // The fuzzer must provide at least one byte array; we keep the domain wide.
    function testFuzz_property(bytes memory data) public {
        // We don't need to constrain 'data' because any calldata that completes the external call
        // should still observe the version() return; keep domain wide so the fuzzer can find
        // differing behavior in the mutant.

        // Make a low-level staticcall to c.version() using arbitrary calldata.
        // The selector for version() is the first 4 bytes of keccak256("version()") = 0xa3ba2a90
        bytes memory sel = abi.encodePacked(bytes4(0xa3ba2a90));
        // Compose calldata: selector + fuzzed data (the mutant and reference ignore extra calldata,
        // but low-level call will still succeed and return the string). This lets the fuzzer vary input.
        bytes memory callData = abi.encodePacked(sel, data);

        (bool ok, bytes memory ret) = address(c).staticcall(callData);

        // decode returned string if call succeeded, otherwise set to empty
        string memory v;
        if (ok) {
            // try to decode as string; if decoding fails, treat as different than "1.0.0"
            // to keep property simple, we catch failures by checking ok first.
            try this._decodeString(ret) returns (string memory s) {
                v = s;
            } catch {
                v = "";
            }
        } else {
            v = "";
        }

        // The universal property: for ALL inputs (all 'data'), the correct contract returns exactly "1.0.0".
        // The mutant that returns "1.0.1" will cause this assertion to fail for some fuzz input(s).
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }

    // helper to decode a returned bytes as string via an external call so try/catch can be used
    function _decodeString(bytes memory b) external pure returns (string memory) {
        return abi.decode(b, (string));
    }
}

