pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the raw calldata bytes passed into a low-level call to version()
    function testFuzz_property(bytes memory calldataBytes) public {
        // admissible domain: we only consider calldata that invokes the external function selector
        // for `version()` (no args). That selector is bytes4(keccak256("version()")) = 0xa3ba2a90.
        // Allow any trailing bytes; keep domain wide so fuzzer can find differences in returned data.
        bytes4 selector = bytes4(keccak256("version()"));
        vm.assume(calldataBytes.length >= 4);
        // require the first 4 bytes equal the selector
        // build a copy with first 4 bytes forced to selector (still fuzzed overall but constrained)
        bytes memory callData = calldataBytes;
        // ensure length at least 4
        if (callData.length < 4) {
            // unreachable due to assume, but keep safe
            callData = new bytes(4);
        }
        // set first 4 bytes to selector
        assembly {
            mstore(add(callData, 32), or(shl(224, selector), and(mload(add(callData, 32)), 0x00ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff)))
        }

        // perform low-level call to c with the prepared calldata
        (bool ok, bytes memory ret) = address(c).call(callData);

        // The universal property we assert: the reference contract always returns abi.encodePacked("1.0.0")
        // from any successful or unsuccessful (but non-reverting) call that uses the version selector.
        // If the call reverted, ok == false; reference never reverts on version(), so ok must be true.
        // We assert both that the call succeeded and returned the exact bytes encoding of "1.0.0".
        bytes memory expected = abi.encodePacked("1.0.0");
        // Single assertion reading c's behavior
        assertTrue(ok && keccak256(ret) == keccak256(expected));
    }
}

