pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the calldata bytes used to call version() via low-level call
    function testFuzz_property(bytes memory callData) public {
        // keep calldata reasonably small to avoid out-of-gas in fuzz harness
        vm.assume(callData.length <= 200);

        // Prepare low-level call to c with the provided calldata.
        // We require that when the call succeeds, it returns the ABI-encoded string "1.0.0".
        (bool success, bytes memory ret) = address(c).call(callData);

        // If the call succeeded, decode the returned bytes as a string if possible.
        // We check that any successful return equals abi.encode(string("1.0.0")).
        if (success) {
            // Single assertion reading c's behavior: the returned data must equal the expected encoding.
            assertTrue(keccak256(ret) == keccak256(abi.encode(string("1.0.0"))));
        } else {
            // If call reverts, the reference contract never reverts for any calldata (its version() is pure),
            // but some malformed calldata may target non-existent function selectors and result in success with empty return
            // (which is still considered success). Reverts are not expected for reference; therefore we assert false
            // only when the reference would revert. To be safe and keep property universal, we accept reverted calls
            // by not asserting anything in that branch. Thus the only assertion is above for successful calls.
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz over a single byte of calldata. The rule: for ANY single-byte calldata
    // passed in a low-level call to address(c), if the call succeeds then the returned
    // raw bytes equal abi.encodePacked("1.0.0"). The mutant (which returns "1.0.1")
    // will cause this assertion to fail for some 1-byte input.
    function testFuzz_property(bytes1 b) public {
        // keep domain wide: a single byte can be any value
        bytes memory data = new bytes(1);
        data[0] = b;

        // perform low-level call so we treat calldata variations; capture success and returndata
        (bool ok, bytes memory ret) = address(c).call(data);

        // We assert a universal property over all single-byte calldata: whenever the call succeeds,
        // the returned raw bytes are exactly abi.encodePacked("1.0.0"). This holds for the reference
        // but is violated by the mutant for some input because it returns "1.0.1" instead.
        bytes memory expected = abi.encodePacked("1.0.0");

        // Single assertion reading c's observable behavior (low-level call result and returndata)
        // true if call failed (we only require the property when call succeeds), otherwise compare returndata
        if (!ok) {
            // If the call reverted, the reference still satisfies the property vacuously for this input
            assertTrue(true);
        } else {
            assertTrue(keccak256(ret) == keccak256(expected));
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call as an arbitrary caller: supply caller address and all parameters.
    // We rely only on c's public surface. The test checks that a call from caller succeeds iff caller == c.depositorAccount().
    function runTest(address caller,
                     uint64 _number,
                     uint64 _timestamp,
                     uint256 _basefee,
                     bytes32 _hash,
                     uint64 _sequenceNumber,
                     bytes32 _batcherHash,
                     uint256 _l1FeeOverhead,
                     uint256 _l1FeeScalar) public {
        // require we can observe depositorAccount
        address depositor = c.depositorAccount();

        // We will perform the state-changing call to c.setL1BlockValues from this contract.
        // To simulate different callers, the test uses the provided `caller` address by requiring
        // that this contract is allowed to act as that address via a precondition: the only feasible
        // way in this constrained environment is to require caller == address(this) so the call originates from this contract.
        // This keeps the test machine-checkable while still distinguishing the original and mutated behaviors.
        require(caller == address(this), "caller must be this contract for the test");

        bool succeeded;
        // Perform the state-changing call and capture whether it reverted using low-level call.
        (succeeded, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // The distinguishing property: succeeded is true exactly when this contract is the depositorAccount.
        // On the original contract P, only depositor can call -> succeeded == (address(this) == depositor)
        // On the mutant M, the condition is inverted and the property will fail.
        assert(succeeded == (address(this) == depositor));
    }

    // Allow receiving ETH if needed by tests (not used here but harmless to include)
    receive() external payable {}
}
